plantuml:
@startuml
title Operate Peering (part 2/2)

|Peering Agent|
start

repeat
:Operate peering arrangement;
|Mediator|
if (External resources needed?) then (yes)
:Discover external resources;
:Negotiate with other CDNs;
else (no)
endif
|SLA-allocator|
:Provision server resources;
|Web Server|
:Replicate content;
:Cache content;
:Select content;
:Route between servers;
:Redirect request;
if (Redirect request) then (yes)
else (no)
stop
endif
:Deliver content;
|Peering Agent|
:Exchange accounting information;
:Perform billing;
backward:Bypass SLA conditions;
repeat while (Termination condition holds?) is (exception)
if (Termination condition holds?) then (yes)
:Disband peering arrangement;
stop
else (no)
:Re-arrange peering arrangement;
stop
endif

@enduml
